#include <bits/stdc++.h>
using namespace std;
int n;
map<int, int> cnt;
vector<int> path;
vector<string> out;
void build() {
    if ((int)path.size() == n) {
        string s;
        for (int i = 0; i < n; i++) s += (i ? " " : "") + to_string(path[i]);
        out.push_back(s);
        return;
    }
    for (auto& [v, c] : cnt) {  // map iterates distinct values in increasing order
        if (c == 0) continue;
        c--; path.push_back(v);
        build();
        path.pop_back(); c++;
    }
}
int main() {
    cin >> n;
    for (int i = 0; i < n; i++) { int x; cin >> x; cnt[x]++; }
    build();
    cout << out.size() << "\n";
    for (auto& s : out) cout << s << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int n, k;
vector<int> path;
vector<string> out;
void build(int start) {
    if ((int)path.size() == k) {
        string s;
        for (int i = 0; i < k; i++) s += (i ? " " : "") + to_string(path[i]);
        out.push_back(s);
        return;
    }
    for (int x = start; x <= n - (k - (int)path.size()) + 1; x++) {
        path.push_back(x);
        build(x + 1);
        path.pop_back();
    }
}
int main() {
    cin >> n >> k;
    build(1);
    cout << out.size() << "\n";
    for (auto& s : out) cout << s << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
vector<int> c, path;
vector<string> out;
void build(int start, int remaining) {
    if (remaining == 0) {
        string s;
        for (size_t i = 0; i < path.size(); i++) s += (i ? " " : "") + to_string(path[i]);
        out.push_back(s);
        return;
    }
    for (int i = start; i < (int)c.size() && c[i] <= remaining; i++) {
        path.push_back(c[i]);
        build(i, remaining - c[i]);
        path.pop_back();
    }
}
int main() {
    int k, target;
    cin >> k;
    c.resize(k);
    for (auto& x : c) cin >> x;
    cin >> target;
    sort(c.begin(), c.end());
    build(0, target);
    cout << out.size() << "\n";
    for (auto& s : out) cout << s << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int n;
vector<bool> col, d1, d2;
int place(int row) {
    if (row == n) return 1;
    int total = 0;
    for (int c = 0; c < n; c++) {
        if (col[c] || d1[row + c] || d2[row - c + n - 1]) continue;
        col[c] = d1[row + c] = d2[row - c + n - 1] = true;
        total += place(row + 1);
        col[c] = d1[row + c] = d2[row - c + n - 1] = false;
    }
    return total;
}
int main() {
    cin >> n;
    col.assign(n, false); d1.assign(2 * n, false); d2.assign(2 * n, false);
    cout << place(0) << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int g[81];
int rowM[9], colM[9], boxM[9];
bool solve() {
    int best = -1, bestCount = 10, bestFree = 0;
    for (int i = 0; i < 81; i++) {
        if (g[i]) continue;
        int r = i / 9, c = i % 9;
        int freeM = ~(rowM[r] | colM[c] | boxM[r / 3 * 3 + c / 3]) & 0x3FE;
        int cnt = __builtin_popcount(freeM);
        if (cnt < bestCount) { best = i; bestCount = cnt; bestFree = freeM; }
    }
    if (best == -1) return true;   // no empty cell left
    if (bestCount == 0) return false;
    int r = best / 9, c = best % 9, b = r / 3 * 3 + c / 3;
    for (int v = 1; v <= 9; v++) {
        int bit = 1 << v;
        if (!(bestFree & bit)) continue;
        g[best] = v; rowM[r] |= bit; colM[c] |= bit; boxM[b] |= bit;
        if (solve()) return true;
        g[best] = 0; rowM[r] ^= bit; colM[c] ^= bit; boxM[b] ^= bit;
    }
    return false;
}
int main() {
    for (int r = 0; r < 9; r++) {
        string line;
        cin >> line;
        for (int c = 0; c < 9; c++) {
            int v = line[c] == '.' ? 0 : line[c] - '0';
            g[r * 9 + c] = v;
            if (v) { int bit = 1 << v; rowM[r] |= bit; colM[c] |= bit; boxM[r / 3 * 3 + c / 3] |= bit; }
        }
    }
    solve();
    for (int r = 0; r < 9; r++) {
        for (int c = 0; c < 9; c++) cout << g[r * 9 + c];
        cout << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int R, C;
vector<string> g;
string word;
bool search(int r, int c, int k) {
    if (k == (int)word.size()) return true;
    if (r < 0 || r >= R || c < 0 || c >= C || g[r][c] != word[k]) return false;
    char saved = g[r][c];
    g[r][c] = '#';
    bool found = search(r + 1, c, k + 1) || search(r - 1, c, k + 1) || search(r, c + 1, k + 1) || search(r, c - 1, k + 1);
    g[r][c] = saved;
    return found;
}
int main() {
    cin >> R >> C;
    g.resize(R);
    for (auto& row : g) cin >> row;
    cin >> word;
    for (int r = 0; r < R; r++)
        for (int c = 0; c < C; c++)
            if (search(r, c, 0)) { cout << "YES\n"; return 0; }
    cout << "NO\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
string s;
bool isPal(int i, int j) { while (i < j) if (s[i++] != s[j--]) return false; return true; }
long long countFrom(int start) {
    if (start == (int)s.size()) return 1;
    long long total = 0;
    for (int end = start; end < (int)s.size(); end++)
        if (isPal(start, end)) total += countFrom(end + 1);
    return total;
}
int main() {
    cin >> s;
    cout << countFrom(0) << "\n";
    return 0;
}

